import {keplar} from '@keplar/sdk'

const client = keplar({apiKey: process.env.KEPLAR_API_KEY})
const place = await client.places.lookup('59.9139,10.7522')
console.log(place.name) // 'Oslo'

const results = await client.geocode('Springfield', {
  country: 'US',
  limit: 5,
})
